const products=[['coat','Folded wool coat',248,'3 colours'],['shirt','Long cotton shirt',118,'One size'],['trouser','Column trouser',148,'2 lengths'],['knit','Open-rib merino layer with an intentionally extended product name',132,'Oat sold out']],state={cart:[],colour:'Mineral',size:'',filters:[],request:0};const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],money=n=>'$'+n;
function route(page,push=true){if(!$('.page[data-page="'+page+'"]'))page='home';$$('.page').forEach(x=>x.classList.toggle('active',x.dataset.page===page));if(push)history.pushState({},'',`#${page}`);close();window.scrollTo(0,0);$('#main').focus({preventScroll:true})}
function grid(){let list=products.filter(p=>!state.filters.includes('impossible')&&(!state.filters.includes('ink')||p[0]==='coat'));$('.grid').innerHTML=list.map((p,i)=>`<article class="card"><div class="art" role="img" aria-label="Abstract study for ${p[1]}"><i>0${i+1}</i></div><h2><a data-product="${p[0]}" href="#product">${p[1]}</a></h2><p><span>${p[3]}</span><b>${money(p[2])}</b></p><button class="button wide card-action" data-product="${p[0]}">${p[0]==='shirt'?'Add safely':'Choose options'}</button></article>`).join('');$('[data-results]').textContent=list.length;$('.grid').hidden=!list.length;$('.empty').hidden=!!list.length}
function product(id){let p=products.find(x=>x[0]===id)||products[0];$('[data-title]').textContent=p[1];$('[data-mobile-title]').textContent=p[1];state.size=id==='shirt'?'One size':'';variant();route('product')}
function variant(){let price=state.colour==='Ink'?258:248;$('[data-price]').textContent=money(price);$('[data-mobile-price]').textContent=money(price);$('[data-colour-label]').textContent=state.colour;$('[data-size-label]').textContent=state.size||'Select a size';$('[data-mobile-variant]').textContent=state.size?`${state.colour} / ${state.size}`:'Choose a size';$('[data-sku]').textContent=`NAR-COAT-${state.colour==='Ink'?'INK':'MIN'}-${state.size||'—'}`;$('[data-media]').textContent=state.colour+' front';$$('[data-colour]').forEach(b=>{let on=b.dataset.colour===state.colour;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',on)});$$('[data-size]').forEach(b=>b.classList.toggle('selected',b.dataset.size===state.size))}
function cart(){let count=state.cart.reduce((n,x)=>n+x.qty,0);$$('[data-count]').forEach(x=>x.textContent=count);let html=state.cart.map(x=>`<article class="line"><div class="art"></div><div><h2>${x.title}</h2><p>${x.colour} / ${x.size} · ${money(x.price)}</p></div><div><label>Quantity <input type="number" min="0" max="9" value="${x.qty}" data-qty="${x.id}"></label><button data-remove="${x.id}">Remove</button><button data-fail>Simulate error</button><p class="message" role="status"></p></div></article>`).join('');$('[data-lines]').innerHTML=html;$('[data-mini]').innerHTML=html||'<p>Your bag is empty.</p>';$('.cart-empty').hidden=!!count;$('.summary').hidden=!count;$('[data-subtotal]').textContent=money(state.cart.reduce((n,x)=>n+x.price*x.qty,0))}
function add(){let msg=$('.message');if(!state.size){msg.textContent='Choose an available size before adding.';$('[data-size]:not(:disabled)').focus();return}msg.textContent='Adding…';let token=++state.request;setTimeout(()=>{if(token!==state.request)return;let x=state.cart[0];if(x)x.qty++;else state.cart=[{id:'coat',title:$('[data-title]').textContent,price:state.colour==='Ink'?258:248,colour:state.colour,size:state.size,qty:1}];cart();msg.textContent='Added to bag.';open('cart')},450)}
let opener;function open(id){close();opener=document.activeElement;$('#'+id).showModal()}function close(){let d=$('dialog[open]');if(d){d.close();opener?.focus();opener=null}}function toast(s){let t=$('.toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}
const reviewStyles=document.createElement('link');reviewStyles.rel='stylesheet';reviewStyles.href='prototype-review.css';document.head.append(reviewStyles);
function review(v){document.body.className=v==='normal'?'':'is-'+v;$('.force-focus')?.classList.remove('force-focus');if(v==='empty'){state.filters=['impossible'];grid();route('collection')}else if(v==='unavailable'){route('product');$('[data-size="L"]').focus()}else if(v==='focus'){route('collection');$('.card-action')?.classList.add('force-focus')}else if(v==='error'){route('product');$('.message').textContent='Update failed. Check the connection and retry.'}else if(v==='normal'){state.filters=[];grid()}}
document.addEventListener('click',e=>{let x=e.target.closest('[data-go]');if(x){e.preventDefault();route(x.dataset.go);return}x=e.target.closest('[data-product]');if(x){e.preventDefault();product(x.dataset.product);return}x=e.target.closest('[data-open]');if(x){open(x.dataset.open);return}if(e.target.closest('[data-close]'))close();x=e.target.closest('[data-colour]');if(x){state.colour=x.dataset.colour;variant()}x=e.target.closest('[data-size]');if(x&&!x.disabled){state.size=x.dataset.size;variant()}if(e.target.closest('[data-add]'))add();if(e.target.closest('[data-reset]')){state.filters=[];grid()}x=e.target.closest('[data-remove]');if(x){state.request++;state.cart=[];cart()}if(e.target.closest('[data-fail]'))e.target.parentElement.querySelector('.message').textContent='Update failed. Previous quantity is preserved; retry when ready.';if(e.target.closest('[data-checkout]'))toast('Checkout hand-off verified; disabled in prototype.');x=e.target.closest('[data-toast]');if(x)toast(x.dataset.toast)});
document.addEventListener('change',e=>{if(e.target.matches('[data-qty]')){let token=++state.request,x=state.cart[0];e.target.disabled=true;setTimeout(()=>{if(token!==state.request)return;x.qty=Math.max(0,+e.target.value||0);if(!x.qty)state.cart=[];cart()},400)}});$('#filters').addEventListener('submit',e=>{e.preventDefault();state.filters=$$('input:checked',e.target).map(x=>x.name);let u=new URL(location);u.searchParams.set('filter',state.filters.join(','));history.pushState({},'',u);grid();close()});$('#review').addEventListener('change',e=>review(e.target.value));window.addEventListener('popstate',()=>route((location.hash||'#home').slice(1),false));grid();variant();cart();route((location.hash||'#home').slice(1),false);
